/* @lc app=leetcode id=3864 lang=kotlin */ class Solution { fun f(P: IntArray, l: Int, r: Int, e: Int, fc: Int): Long = (r - l).let { L -> (P[r] - P[l]).let { X -> (if (X == 0) fc.toLong() else L.toLong() * X * e).let { direct -> if (L % 2 == 0) minOf(direct, f(P, l, (l + r) / 2, e, fc) + f(P, (l + r) / 2, r, e, fc)) else direct } } } fun minCost(s: String, encCost: Int, flatCost: Int): Long = s.runningFold(0) { a, c -> a + (c - '0') }.toIntArray().let { P -> f(P, 0, s.length, encCost, flatCost) } }